import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, '..');

const SKIP_DIRS = ['node_modules', '.git', '.wrangler', '.agent', 'data', 'scripts', 'tools', 'category'];
// tools and category are generated by generate-static-pages.mjs, so we'll just regenerate them

const ADSENSE_META = '<meta name="google-adsense-account" content="ca-pub-7088331504377019">';
const CONSENT_SCRIPT = '<script src="/js/consent.js"></script>';

function processFile(filePath) {
    if (!filePath.endsWith('.html')) return;
    
    // Skip admin/submissions completely
    const isExcluded = filePath.includes('/admin') || filePath.endsWith('/submissions.html');

    const original = fs.readFileSync(filePath, 'utf8');
    let updated = original;

    // Remove any hardcoded adsbygoogle script
    updated = updated.replace(/<script[^>]*src=["']https:\/\/pagead2\.googlesyndication\.com\/pagead\/js\/adsbygoogle\.js[^>]*><\/script>/g, '');

    // Add AdSense Meta Tag and Consent Script before </head> if they don't exist
    if (!isExcluded) {
        if (!updated.includes(ADSENSE_META)) {
            updated = updated.replace('</head>', `    ${ADSENSE_META}\n</head>`);
        }
        if (!updated.includes(CONSENT_SCRIPT)) {
            updated = updated.replace('</head>', `    ${CONSENT_SCRIPT}\n</head>`);
        }
    }

    if (updated !== original) {
        fs.writeFileSync(filePath, updated, 'utf8');
        console.log(`Updated: ${path.relative(ROOT, filePath)}`);
    }
}

function walk(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
        if (SKIP_DIRS.includes(entry.name)) continue;
        
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            walk(fullPath);
        } else {
            processFile(fullPath);
        }
    }
}

console.log('Injecting consent scripts and meta tags...');
walk(ROOT);
console.log('Done.');
